def iconName(self, background_color):
    # Check if the background color is dark
    is_dark = (background_color[0] * 0.299 + background_color[1] * 0.587 + background_color[2] * 0.114) < 186
    if is_dark:
        return '{}_white'.format(self._iconNamePrefix)
    return '{}_black'.format(self._iconNamePrefix)
